        heading: '単位と数値感覚',
        body: `密度の問題は、単位をそろえるところでつまずくことが多い。

■ 単位の変換
1 cm³ ＝ 1 mL
1 L ＝ 1000 cm³ ＝ 1000 mL
1 m³ ＝ 1000000 cm³
1 kg ＝ 1000 g

例）体積 1.5 L、質量 1.2 kg の液体の密度
体積 1.5 L ＝ 1500 cm³、質量 1.2 kg ＝ 1200 g
密度 ＝ 1200 ÷ 1500 ＝ 0.80 g/cm³
（この値はエタノールに近い）

■ 覚えておきたいおもな密度（g/cm³）
エタノール 0.79／氷 0.92／水 1.00／アルミニウム 2.70／鉄 7.87／銅 8.96／鉛 11.3／水銀 13.5／金 19.3

■ 数値感覚を持つ
・気体の密度はきわめて小さい（空気は約 0.0012 g/cm³）。
・水より小さい固体・液体は 1 未満の値（氷・エタノール・油・木材）。
・金属はほとんどが 2 以上で、多くは 7〜11 のあたりに集まる。

⚠ 注意：計算して「アルミニウムの密度が 27 g/cm³ になった」など、明らかに常識はずれの値が出たら、体積と質量を逆に割った可能性が高い。密度の値の相場を知っていれば、その場で誤りに気づける。

★ ポイント：割り算の向きを迷ったら、単位を見る。求めたいのは g/cm³ なので、g を cm³ で割る、と単位から式を組み立てられる。`,
