        heading: '三つの求め方',
        body: `密度に関する計算は次の三通りに分けられる。もとになる式は一つだけである。

■ ①密度を求める（質量と体積が与えられる）
密度 ＝ 質量 ÷ 体積
例）質量 158 g、体積 20 cm³ の金属
158 ÷ 20 ＝ 7.9 g/cm³ → 鉄

■ ②質量を求める（密度と体積が与えられる）
質量 ＝ 密度 × 体積
例）密度 2.7 g/cm³ のアルミニウム 30 cm³ の質量
2.7 × 30 ＝ 81 g

■ ③体積を求める（密度と質量が与えられる）
体積 ＝ 質量 ÷ 密度
例）密度 8.96 g/cm³ の銅 89.6 g の体積
89.6 ÷ 8.96 ＝ 10 cm³

■ 単位から式を組み立てる方法
求めたいものの単位を書いてから考えると、公式を暗記していなくても立式できる。
・g/cm³ がほしい → g を cm³ で割る
・g がほしい → g/cm³ に cm³ をかける（cm³ が約分されて g が残る）
・cm³ がほしい → g を g/cm³ で割る

★ ポイント：三つの式を別々に暗記するより、「密度＝質量÷体積」だけを覚えて、あとは分数の変形で導くほうが確実である。テストで公式を思い出せない事態を防げる。`,
