        body: `測定器具の使い方は、そのまま入試の記述問題になる。

■ メスシリンダー
・水平でしっかりした台に置く。手に持って読んではいけない。
・目線を液面と同じ高さにし、真横から読む。上から見ると実際より多く、下から見ると少なく読んでしまう。
・水はガラスに引きつけられて、中央がへこんだ形（メニスカス）になる。読むのはへこんだ中央のいちばん低いところである。
・最小目盛りの 1/10 まで目分量で読む。最小目盛りが 1 cm³ なら「50.0」「68.4」のように小数第1位まで書く。

例）最小目盛り 1 cm³ のメスシリンダーで、液面が 46 と 47 の間の、47 に近いところにある → 46.8 cm³ のように読む。

■ 電子てんびん・上皿てんびん
・水平な台に置く。電子てんびんは物をのせる前に表示を 0 にする（風袋引き）。
・粉末をはかるときは薬包紙をのせてから 0 にすると、粉だけの質量が読める。
・上皿てんびんでは、利き手側の皿に分銅をのせ、重い分銅から順にのせて調整する。

⚠ 注意：メスシリンダーで「50 cm³ の水を正確にはかりとる」ことはできない。正確に一定量をはかりとる器具はメスフラスコやホールピペットである。メスシリンダーはおよその体積をはかる器具だと理解しておく。

★ ポイント：測定値を書くとき「50」ではなく「50.0」と書くことに意味がある。小数第1位の 0 は「目分量で読んでちょうど 0 だった」という情報を表しており、これを省くと測定の精度が伝わらない。`,
