        body: `入試ではグラフをそのまま読ませるだけでなく、次のような応用が出る。

■ ①同じ直線上かどうかで物質を判定する
「A・B・C・D の4点のうち、同じ物質でできているものはどれとどれか」という問い。原点と各点を結んだ直線が同じ傾きになるものを探す。
例）P(5, 13.5)、Q(20, 54) → 13.5 ÷ 5 ＝ 2.7、54 ÷ 20 ＝ 2.7 → 同じ物質（アルミニウム）

■ ②グラフから未知の値を求める
「この物質 25 cm³ の質量はいくらか」→ 密度 2.7 なので 2.7 × 25 ＝ 67.5 g。グラフの範囲外でも、比例の関係を使えば計算できる。

■ ③原点を通らない直線
容器に液体を入れながら全体の質量をはかると、グラフは縦軸の切片が容器の質量になる直線になる。この場合、傾きは液体の密度だが、ある点の質量を体積で割っても密度にはならない。
例）切片 60 g、点（40 cm³, 91.6 g）→ 液体の質量は 91.6 － 60 ＝ 31.6 g → 密度 31.6 ÷ 40 ＝ 0.79 g/cm³

⚠ 注意：原点を通らないグラフで、点の座標をそのまま割ると誤りになる。まず「グラフが原点を通っているか」を確認する習慣をつける。

■ ④温度によるグラフの変化
温度が上がると多くの物質は体積が増えるので、同じ質量でも体積が大きくなり、直線の傾きはわずかにゆるくなる（密度が小さくなる）。

★ ポイント：グラフ問題では、まず「原点を通るか」「軸の単位は何か」の二点を確認する。この確認を先にするだけで、応用問題の失点が大きく減る。`,
