        body: `■ 標準的な発生方法
石灰石（炭酸カルシウム）にうすい塩酸を加える。石灰石の代わりに、貝がら・卵のから・チョーク・大理石を使っても同じ気体が出る。いずれも主成分が炭酸カルシウムだからである。

■ 他の発生方法
・炭酸水素ナトリウム（重そう）を加熱する（炭酸ナトリウム・水・二酸化炭素に分かれる）。ホットケーキがふくらむのはこの反応である。
・炭酸水素ナトリウムにうすい塩酸を加える。
・有機物を燃やす。
・生物の呼吸（吸う息と吐く息の比較実験）。

■ 確認方法
発生した気体を石灰水に通す。白くにごれば二酸化炭素である。これは炭酸カルシウムという水に溶けない白い固体ができるためである。

⚠ 注意：さらに二酸化炭素を通し続けると、白いにごりはいったん消えて再び透明になる。これは炭酸カルシウムが二酸化炭素と水にとけて別の物質になるためである。「にごったあと透明になったから二酸化炭素ではない」と判断しないこと。

■ 発生量を増やすには
うすい塩酸のかわりに濃い塩酸を使うと反応は速くなるが、発生する気体の総量は石灰石と塩酸のうち、先になくなるほうで決まる。石灰石を粉にすると表面積が増えるので反応は速くなるが、これも総量は変わらない。

★ ポイント：「反応を速くする条件」と「発生する総量を決める条件」を混同しない。速さは濃さ・温度・表面積、総量は反応する物質の量で決まる。`,
