        body: `■ 原理
水を満たした集気びん（または試験管）を、水そうの中でさかさまに立てる。そこへ導管の先を入れて気体を送りこむと、気体は水より上にたまろうとするため、水を押し下げながら容器の上部にたまっていく。「気体が水と置きかわる」ので置換法という。

■ 使える条件
その気体が水に溶けにくいこと。溶けてしまう気体では、送りこんでも水に吸収されて集まらない。
水上置換法で集める代表：酸素・水素・窒素・メタン・ヘリウム
二酸化炭素は少し溶けるが、短時間なら水上置換法でも集められる。純度が必要なときはこちらを選ぶ。

■ 操作の要点
・集気びんに水を満たすときは、あわが残らないようにする。あわが残っていると、そのぶん集まった体積を多く見積もってしまう。
・はじめに出てくる気体は集めない。装置の中にもともと入っていた空気が押し出されてくるためである。しばらく出させてから容器に導く。
・集め終わったら、水中でガラス板（または栓）をしてから取り出す。空気が入るのを防ぐためである。
・気体を集めた容器は、水上置換法で集めたときはさかさまのまま置くか、気体の密度に応じて置き方を決める。

⚠ 注意：実験終了時は必ず「導管を水そうから抜く → 火を消す」の順で行う。逆にすると、冷えて縮んだ試験管内に水が逆流し、急冷された試験管が割れる。

★ ポイント：「はじめの気体を捨てる理由」と「導管を先に抜く理由」は、どちらも記述で頻出。前者は空気が混ざるから、後者は水の逆流で試験管が割れるから、と対にして覚える。`,
