        body: `■ 定義
溶解度とは、ある温度で水 100 g に溶かすことのできる溶質の最大の質量を、g の数値で表したものである。

例）硝酸カリウムの 20℃ における溶解度は 32。これは「20℃ の水 100 g に硝酸カリウムは 32 g まで溶ける」という意味である。

⚠ 注意：基準は「水 100 g」であって「水溶液 100 g」ではない。20℃ の硝酸カリウム飽和水溶液は、水 100 g ＋ 硝酸カリウム 32 g ＝ 132 g となる。ここを取りちがえると、濃度の計算がすべてずれる。

■ 飽和水溶液
それ以上溶質を溶かすことのできない状態の水溶液を飽和水溶液という。
・飽和水溶液に同じ溶質をさらに加えても、加えた分はそのまま溶け残る。
・ただし別の物質なら、飽和していても溶けることがある。飽和は物質ごとの話である。

例）20℃ の水 100 g に硝酸カリウムを 32 g 溶かして飽和させたあと、食塩を加えると食塩は溶ける。

■ 水の量が変わったら
溶解度は水 100 g あたりの値なので、水の量に比例して考える。
例）40℃ の硝酸カリウムの溶解度は 64。40℃ の水 150 g には
64 × 150 ÷ 100 ＝ 96 g まで溶ける。
例）40℃ の水 50 g には 64 × 0.5 ＝ 32 g まで溶ける。

★ ポイント：問題を読んだら、まず「水は何 g か」を確認する。100 g でない場合は、必ず比を使って読みかえてから計算に入る。`,
