        heading: '曲線の傾きが意味するもの',
        body: `曲線の傾き（温度を変えたときの溶解度の変化の大きさ）は、実験のやり方を決める。

■ 傾きが大きい物質（硝酸カリウム・ミョウバン）
・高温で大量に溶かし、冷やせば大量の結晶が出る → 冷却による再結晶に向く。
例）60℃ の水 100 g に硝酸カリウムを溶けるだけ溶かし（109 g）、20℃ に冷やすと 109 － 32 ＝ 77 g の結晶が出る。

■ 傾きが小さい物質（塩化ナトリウム）
・冷やしてもほとんど結晶が出ない → 冷却による再結晶に向かない。
例）60℃ の飽和水溶液（37.1 g）を 20℃ に冷やしても 37.1 － 35.8 ＝ 1.3 g しか出ない。
・そこで塩化ナトリウムは、水を蒸発させて取り出す。海水から塩をつくるとき、加熱や天日で水を蒸発させるのはこのためである。

■ 溶解度が小さい物質（ホウ酸）
・そもそも溶ける量が少ないので、少量の溶質でもすぐ飽和する。
・傾きは相対的には大きい（0℃ 2.8 → 60℃ 14.9 で約5倍）ので、冷却で結晶を取り出すこと自体はできるが、量は少ない。

■ 曲線の形と粒子のようす
温度が上がると、水の粒子の運動が激しくなり、固体の表面から粒子をはがして取りこむ力が強くなる。そのため多くの固体では溶解度が大きくなる。増え方の差は、溶質の粒子どうしの結びつきの強さのちがいによる。

★ ポイント：「なぜ食塩は冷やしても結晶が出にくいのか」と問われたら、「塩化ナトリウムは温度による溶解度の変化が小さいから」と答える。「食塩がよく溶けるから」では理由になっていない。`,
