        body: `■ 定義
固体の物質をいったん水に溶かし、温度を下げたり水を蒸発させたりして、再び結晶として取り出す操作を再結晶という。

■ 二つの方法
①温度を下げる方法
高温で飽和させた水溶液を冷やす。温度が下がると溶解度が小さくなるので、溶けきれなくなった分が結晶になって出てくる。
向いている物質：硝酸カリウム、ミョウバン（曲線の傾きが大きい）

②水を蒸発させる方法
水溶液を加熱したり、放置して自然に蒸発させたりして、溶媒である水を減らす。水が減れば溶かせる量も減るので、あふれた分が結晶になる。
向いている物質：塩化ナトリウム（曲線の傾きが小さい）

■ 結晶とは
いくつかの平面で囲まれた、規則正しい形をした固体を結晶という。その物質の粒子が規則正しく並んでできているため、物質ごとに決まった形になる。
硝酸カリウム：細長い針状
塩化ナトリウム：立方体（サイコロ状）
ミョウバン：正八面体
ホウ酸：六角形の板状

結晶は純粋な物質（純物質）である。混じり物がある状態では、規則正しい形にならない。

★ ポイント：再結晶で「純粋な物質が得られる」という点が最大のねらいである。「結晶を大きくつくる」実験に見えても、目的は精製であることを押さえる。`,
