        body: `■ よく問われる記述とその答え方

Q「硝酸カリウムと塩化ナトリウムでは、冷却による再結晶に適しているのはどちらか。理由も書け」
A「硝酸カリウム。温度による溶解度の変化が大きく、冷やすと多くの結晶が出るから。塩化ナトリウムは温度による溶解度の変化が小さく、冷やしてもほとんど結晶が出ない。」

Q「不純物として少量の塩化ナトリウムをふくむ硝酸カリウムから、純粋な硝酸カリウムを取り出す方法を書け」
A「高温の水にすべて溶かし、ゆっくり冷やす。硝酸カリウムは溶解度をこえて結晶になるが、塩化ナトリウムは量が少なく溶解度に達しないので溶けたまま残る。これをろ過して結晶を集める。」

Q「取り出した結晶の表面をどうするか」
A「冷たい水で軽く洗うか、ろ紙にはさんで水分を取り除く。結晶の表面についた水溶液には不純物がふくまれているため。」

■ 数値のわなに注意する
・「水 100 g」か「水溶液 100 g」か
・「溶かした量」か「溶ける限界の量」か
・冷却なのか蒸発なのか、両方なのか
・水の質量は冷却では変わらないが、蒸発では減る

■ グラフを描かせる問題
「冷やしていったときに出てくる結晶の質量と温度の関係をグラフに表せ」
飽和する温度までは結晶が出ない（0のまま）、そこから温度が下がるにつれて析出量が増えていく、という形になる。溶解度曲線を上下に裏返したような曲線になる。

★ ポイント：長い実験問題ほど、条件を表に整理してから解く。温度・水・溶質の三列の表をつくれば、どの段階で何が変わったかが一目でわかる。`,
