        heading: '密度の変化と、水の例外',
        body: `■ 密度はどうなるか
質量は変わらず体積が変わるので、密度は変化する。体積が大きくなれば密度は小さくなる。
ふつうの物質：固体 ＞ 液体 ＞ 気体 の順に密度が大きい。だから固体は自分の液体に沈む。

例）とけたろうの中に固まったろうのかけらを入れると沈む。

■ 水だけが例外
水は液体から固体（氷）になるとき、体積が約 1.1 倍に増える。
水 1.00 g/cm³ → 氷 0.92 g/cm³
そのため氷は水に浮く。

理由：水の粒子は凍るときに、すきまの多い規則正しい構造をつくるためである。

例）ペットボトルに水をいっぱいに入れて凍らせると、ふくらんだり破裂したりする。冬に水道管が破裂するのも同じ理由である。岩のすきまに入った水が凍って岩を割る（凍結による風化）のもこの性質による。

■ 気体になったときの体積
水 1 cm³（1 g）が 100℃ の水蒸気になると、体積は約 1700 cm³ になる。密閉容器の中で液体を加熱すると危険なのはこのためである。

■ 実験でよくある観察
・熱湯をかけると、エタノールを少量入れた袋がふくらむ → エタノールが気化して体積が大きくなったため。袋の中の質量は変わらない。
・冷やすと袋はしぼむ → 気体が液体にもどったため。

⚠ 注意：袋がふくらんだからといって、エタノールが増えたわけではない。増えたのは体積だけで、質量は変わらない。

★ ポイント：「質量は変わらない／体積は変わる／密度は変わる」の三点セットを、どの状態変化の問題でも最初に確認する。`,
