        heading: '蒸留で分けられるもの・分けられないもの',
        body: `■ 蒸留が使える場面
①沸点のちがう液体どうしを分ける
例）水とエタノール、石油の成分どうし

②液体に溶けている固体から、液体だけを取り出す
例）海水から真水を得る（水だけが蒸気になり、塩は残る）
例）食塩水を蒸留すると、フラスコに食塩が残り、集まるのは純粋な水である

③水道水から純粋な水（蒸留水）をつくる

■ ろ過・蒸発との使い分け
・溶けていない固体を分ける → ろ過
・溶けている固体を取り出す（液体は捨てる） → 蒸発
・溶けている液体を取り出す、または液体のほうがほしい → 蒸留

例）食塩水から食塩がほしい → 蒸発でよい
例）食塩水から水がほしい → 蒸留が必要
どちらもほしい → 蒸留（フラスコに食塩、試験管に水）

■ うまく分けられない場合
沸点の差が小さい液体どうしは、一回の蒸留ではきれいに分かれない。何度もくり返すか、精密な装置（分留塔）を使う。

■ 蒸留水の性質
蒸留水は溶けていた物質を含まないので、電流を通しにくい。水道水は微量の物質が溶けているので、蒸留水よりわずかに電流を通す。この差は「純物質か混合物か」を確かめる実験にも使える。

★ ポイント：蒸留の目的を毎回確認する。「何を取り出したいのか」で、蒸留と蒸発のどちらを選ぶかが決まる。`,
