        heading: '身近な蒸留と石油の分留',
        body: `■ 分留（分別蒸留）
沸点のちがいを利用して、混合物を何種類もの成分に分けて取り出す操作を分留という。蒸留を段階的に行うものと考えればよい。

■ 石油（原油）の分留
原油は、沸点のちがう多くの物質が混ざった混合物である。加熱して蒸留塔に送りこむと、沸点の低いものほど高いところまで上がり、それぞれの高さで液体にもどって取り出される。

塔の上のほうから順に（沸点の低い順）
石油ガス（〜約35℃）→ ガソリン・ナフサ（約35〜180℃）→ 灯油（約170〜250℃）→ 軽油（約240〜350℃）→ 重油・アスファルト（350℃〜）

ガソリンは自動車の燃料、ナフサはプラスチックの原料、灯油はストーブやジェット燃料、軽油はディーゼル車、重油は船舶や発電に使われる。

■ 液体空気の分留
空気を冷やして液体にし、温度を上げていくと、沸点の低い窒素（－196℃）が先に気体になって出てくる。あとに残るのが酸素（－183℃）である。工業的に窒素・酸素・アルゴンをつくる方法である。

⚠ 注意：この場合、沸点の低い窒素が先に出る。液体空気を蒸留すると「先に酸素が出る」としないよう注意する。

■ その他の蒸留の利用
・海水から真水をつくる（海水淡水化）
・ウイスキー・焼酎などの蒸留酒をつくる
・実験用の蒸留水をつくる
・香料を植物から取り出す（水蒸気蒸留）

★ ポイント：分留の問題では、必ず「沸点の低いものから先に出てくる」を軸に考える。どの成分がどの順に取り出されるかは、沸点の順序で決まる。`,
